<script setup lang="ts">
import { computed } from 'vue'; import { useRoute } from 'vue-router'; import AppStatusChip from '@/Components/AppStatusChip.vue'; import PageHeader from '@/Components/layout/PageHeader.vue'; import { useAdministratorStore } from '@/stores/administrator.store'
const route = useRoute(); const store = useAdministratorStore(); const user = computed(() => store.getUserById(route.params.userId as string)); const roleLabels = { administrator: 'Administrateur', supervisor: 'Superviseur', teamLeader: 'Chef d’équipe', agent: 'Agent' }
</script>
<template><div class="mx-auto w-full max-w-[1050px]"><PageHeader><template #title>{{ user ? `${user.firstName} ${user.lastName}` : 'Utilisateur introuvable' }}</template><template #description>Profil, accès et affectation de l’utilisateur.</template><template #actions><v-btn variant="outlined" prepend-icon="mdi-arrow-left" :to="{ name: 'admin-users' }">Retour</v-btn><v-btn v-if="user" color="primary" prepend-icon="mdi-pencil-outline" :to="{ name: 'admin-user-edit', params: { userId: user.id } }">Modifier</v-btn></template></PageHeader><v-alert v-if="!user" type="error" variant="tonal" title="Utilisateur introuvable" /><div v-else class="grid gap-6 lg:grid-cols-[1fr_320px]"><v-card><v-card-title class="px-6 py-5">Informations professionnelles</v-card-title><v-divider /><v-card-text class="grid gap-5 px-6 py-6 sm:grid-cols-2"><div><p class="text-xs text-[#848484]">E-mail</p><p class="mt-1 font-medium">{{ user.email }}</p></div><div><p class="text-xs text-[#848484]">Téléphone</p><p class="mt-1 font-medium">{{ user.phone }}</p></div><div><p class="text-xs text-[#848484]">Matricule</p><p class="mt-1 font-medium">{{ user.employeeNumber }}</p></div><div><p class="text-xs text-[#848484]">Équipe</p><p class="mt-1 font-medium">{{ user.team }}</p></div><div><p class="text-xs text-[#848484]">Rôle</p><p class="mt-1 font-medium">{{ roleLabels[user.role] }}</p></div></v-card-text></v-card><v-card><v-card-text class="pa-6"><div class="flex items-center justify-between"><span class="font-bold">État du compte</span><AppStatusChip :status="user.status" /></div><v-divider class="my-5" /><v-btn block variant="tonal" :color="user.status === 'disabled' ? 'success' : 'error'" :prepend-icon="user.status === 'disabled' ? 'mdi-account-check-outline' : 'mdi-account-off-outline'" @click="store.toggleUserStatus(user.id)">{{ user.status === 'disabled' ? 'Réactiver le compte' : 'Désactiver le compte' }}</v-btn></v-card-text></v-card></div></div></template>

